// one item per recipient, from the OFFER webhook body
const b = $('OFFER').first().json.body;
return b.recipients.map(r => ({ json: {
  number: r.phone_intl, message_id: r.message_id, lead_id: r.lead_id,
  text: b.message, image_url: b.offer.image_url || '', callback_url: b.callback_url || ''
}}));

const rows = $input.all().map(i => i.json);
let cfg = rows[0]?.cfg ?? {};
if (!Object.keys(cfg).length && rows.length) {
  cfg = Object.fromEntries(
    rows
      .filter(r => (r.config_key ?? r.key) !== undefined)
      .map(r => [r.config_key ?? r.key, r.config_value ?? r.value])
  );
}

const wh = $('Webhook').first().json;
const body = { ...(wh.body ?? {}) };
delete body.apikey;

cfg.evolution_url = cfg.evolution_url || cfg.evolution_api_url || cfg.evolution_base_url;
const REQUIRED = ['evolution_url', 'supabase_url', 'media_bucket'];
const bad = REQUIRED.filter(k => !cfg[k] || cfg[k] === 'CHANGE_ME');
if (bad.length) {
  throw new Error(`Missing config: ${bad.join(', ')} | keys seen: ${Object.keys(cfg).join(', ') || 'NONE'}`);
}

const event_raw = String(body.event ?? '');
const event = event_raw.trim().toLowerCase().replace(/[_\s]+/g, '.');
const d = Array.isArray(body.data) ? body.data[0] : body.data;

let route = 'ignore';
if (event.endsWith('messages.upsert')) route = 'message';
else if (event.endsWith('messages.update')) route = 'status';
else if (!event && d?.key && d?.message) route = 'message';
else if (!event && d?.keyId && d?.status) route = 'status';

return [{
  json: {
    evolution_url: String(cfg.evolution_url).replace(/\/+$/, ''),
    supabase_url: String(cfg.supabase_url).replace(/\/+$/, ''),
    media_bucket: cfg.media_bucket,
    instance: body.instance || cfg.evolution_instance || 'whatsapp_agent',
    evolution_api_key: cfg.evolution_api_key ?? '',
    service_key: cfg.supabase_service_role_key ?? '',
    ai_model: cfg.ai_model ?? '',
    transcribe_model: cfg.transcribe_model ?? '',
    system_prompt: cfg.system_prompt ?? '',
    event_raw, event, route,
    body,
  },
  pairedItem: { item: 0 },
}];

// Normalize the form payload. Dedupe is done in Supabase (by phone), not in workflow static data.
const clean = v => { if (v == null) return null; const s = String(v).trim().replace(/\s+/g, ' '); return s || null; };

const parsePhone = (raw, cc = '20') => {
  const c = clean(raw);
  if (!c) return { digits: null, valid: false };
  let n = c.replace(/[^\d+]/g, '');
  if (n.startsWith('00')) n = '+' + n.slice(2);
  let d;
  if (n.startsWith('+')) d = n.slice(1);
  else if (/^01\d{9}$/.test(n)) d = cc + n.slice(1);          // Egyptian mobile 01XXXXXXXXX
  else if (/^0\d{6,13}$/.test(n)) d = cc + n.slice(1);
  else d = n;
  d = d.replace(/\D/g, '');
  return { digits: /^[1-9]\d{6,14}$/.test(d) ? d : null, valid: /^[1-9]\d{6,14}$/.test(d) };
};

// Form option -> value the CRM understands (see LeadSource in the app)
const SOURCE_MAP = { 'facebook ads': 'Meta Lead Ads', 'instagram ads': 'Meta Lead Ads', 'website': 'Website', 'whatsapp': 'WhatsApp', 'referral': 'Referral' };

const out = [];
for (const item of $input.all()) {
  const d = item.json?.body ?? item.json ?? {};
  const email = clean(d['Email'])?.toLowerCase() ?? null;
  const phone = parsePhone(d['Phone / WhatsApp']);
  const interest = clean(d['What are you interested in?']);
  const location = clean(d['Location']);
  const notes = [interest && `Interest: ${interest}`, location && `Location: ${location}`, clean(d['Additional Notes'])].filter(Boolean).join(' | ') || null;
  const src = clean(d['Lead Source'])?.toLowerCase();
  const submitted = new Date(clean(d.submittedAt) ?? Date.now());

  out.push({ json: {
    full_name: clean(d['Full Name']),
    business_name: clean(d['Restaurant / Business Name']),
    business_type: clean(d['Business Type'])?.toLowerCase() ?? null,
    interest, location, notes,
    phone_digits: phone.digits,
    phone_valid: phone.valid,
    email: email && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ? email : null,
    lead_source: SOURCE_MAP[src] ?? 'Website',
    status: 'New',
    submitted_at: isNaN(submitted) ? new Date().toISOString() : submitted.toISOString(),
  }});
}
return out;

