const base = $('Build booking message1').item.json;
const cal = $input.first().json || {};

const meetLink =
  cal.hangoutLink ||
  cal.conferenceData?.entryPoints?.find((ep) => ep.entryPointType === 'video')?.uri ||
  cal.conferenceData?.entryPoints?.[0]?.uri ||
  '';

const calendarLink = cal.htmlLink || '';

let finalText = base.text;
if (base.event !== 'booking.cancelled') {
  if (meetLink) {
    finalText = `${base.text}\nGoogle Meet: ${meetLink}`;
  } else if (calendarLink) {
    finalText = `${base.text}\nCalendar Event: ${calendarLink}`;
  }
}

return [{
  json: {
    ...base,
    calendar_event_id: cal.id || null,
    calendar_link: calendarLink,
    meet_link: meetLink,
    final_text: finalText,
    notes: base.notes || ''
  }
}];

// BOOKINGS payload -> WhatsApp text + Calendar ISO times + CRM fields
const raw = $input.first().json;
const b = raw?.body ?? raw ?? {};
const lead = b.lead ?? {};
const booking = b.booking ?? {};

const fullName = String(lead.name || lead.full_name || '').trim();
const first = fullName.split(/\s+/)[0] || 'there';
const phoneIntl = String(lead.phone_intl || lead.phone || '').trim();
const email = String(lead.email || '').trim();
const interest = String(booking.interest || b.interest || '').trim();
const notes = String(booking.notes || b.notes || '').trim();
const dateStr = String(booking.date || '').trim();
const timeStr = String(booking.time || '10:00').trim();
const tz = String(booking.timezone || 'Africa/Cairo').trim();
const ev = b.event || 'booking.created'; // booking.created | booking.updated | booking.cancelled

// Build safe start & end ISO strings
let startDateObj = booking.start_at ? new Date(booking.start_at) : null;
if (!startDateObj || Number.isNaN(startDateObj.getTime())) {
  const normalizedTime = /^\d{1,2}:\d{2}$/.test(timeStr)
    ? `${timeStr.padStart(5, '0')}:00`
    : timeStr;
  const candidate = dateStr ? `${dateStr}T${normalizedTime}` : '';
  startDateObj = candidate ? new Date(candidate) : new Date();
  if (Number.isNaN(startDateObj.getTime())) {
    startDateObj = new Date();
  }
}

const endDateObj = booking.end_at && !Number.isNaN(new Date(booking.end_at).getTime())
  ? new Date(booking.end_at)
  : new Date(startDateObj.getTime() + 30 * 60000);

const when = `${dateStr || startDateObj.toISOString().slice(0, 10)} at ${timeStr} (${tz})`;

let text, status;
if (ev === 'booking.cancelled') {
  text = `Hi ${first}, your Menuopoly demo on ${when} has been cancelled. Tell us what time suits you and we will book a new one.`;
  status = 'Cancelled';
} else if (ev === 'booking.updated') {
  text = `Hi ${first}, your Menuopoly demo is now set for ${when}. We will show you how the menu looks on your customers' phones and how ordering works.`;
  status = 'Confirmed';
} else {
  text = `Hi ${first}, your Menuopoly demo is confirmed for ${when}. It takes 15 minutes. Reply here if you need to change the time.`;
  status = 'Confirmed';
}

return [{
  json: {
    event: ev,
    number: phoneIntl,
    phone_digits: phoneIntl.replace(/\D/g, ''),
    full_name: fullName,
    lead_name: fullName,
    email,
    interest,
    notes,
    date: dateStr,
    time: timeStr,
    timezone: tz,
    start_at: startDateObj.toISOString(),
    end_at: endDateObj.toISOString(),
    text,
    status,
    booking_id: booking.id || null,
    callback_url: b.callback_url || ''
  }
}];

const b = $input.first().json.body || {};
const rawPhone = String(b.lead?.phone_intl || '');
const number = rawPhone.replace(/\D/g, '');
const first = String(b.lead?.name || '').trim().split(/\s+/)[0] || 'عميلنا';
const place = String(b.lead?.restaurant_name || 'مطعمك').trim();

const text = `مرحباً ${first}، معك فريق Menuopoly. حبّينا نتابع معك بخصوص ${place}. هل يناسبك وقت قصير هذا الأسبوع لعرض سريع (١٥ دقيقة)؟`;

return [{
  json: {
    number,
    rawPhone,
    text,
    task_id: b.task?.id ?? null,
    lead_id: b.lead?.id ?? null,
    timestamp: new Date().toISOString()
  }
}];

const b = $input.first().json.body || {};
const rawPhone = String(b.lead?.phone_intl || '');
const number = rawPhone.replace(/\D/g, '');
const first = String(b.lead?.name || '').trim().split(/\s+/)[0] || 'عميلنا';
const place = String(b.lead?.restaurant_name || 'مطعمك').trim();

const text = `مرحباً ${first}، حابين نطّمن لو شفت رسالتنا بخصوص ${place}. لو وقتك يسمح بعرض سريع (١٥ دقيقة) هذا الأسبوع، قول لنا الموعد المناسب لك 😊`;

return [{
  json: {
    number,
    rawPhone,
    text,
    stage: 'follow_up',
    task_id: b.task?.id ?? null,
    lead_id: b.lead?.id ?? null,
    timestamp: new Date().toISOString()
  }
}];

return items.map((item) => {
  const data = item.json || {};

  let cleanPhone = String(data.lead_phone || data.phone_digits || '').replace(/\D/g, '');
  if (cleanPhone.startsWith('00')) cleanPhone = cleanPhone.slice(2);
  if (/^01[0125]\d{8}$/.test(cleanPhone)) cleanPhone = '2' + cleanPhone;
  else if (/^1[0125]\d{8}$/.test(cleanPhone)) cleanPhone = '20' + cleanPhone;

  const cleanMessage = String(data.final_message_content || '')
    .replace(/\r\n/g, '\n')
    .trim();

  // استخراج الاهتمامات والموقع من lead_notes بدون تكرار
  const rawNotes = String(data.lead_notes || '');
  const interestMatches = [...rawNotes.matchAll(/Interest:\s*([^|\n]+)/gi)].map((m) => m[1].trim());
  const locationMatches = [...rawNotes.matchAll(/Location:\s*([^|\n]+)/gi)].map((m) =>
    m[1].trim().replace(/^cario$/i, 'Cairo')
  );

  const uniqueInterests = [...new Set(interestMatches)];
  const uniqueLocations = [...new Set(locationMatches.map((x) => x.toLowerCase()))].map((loc) =>
    loc === 'cairo' ? 'Cairo' : loc === 'egypt' ? 'Egypt' : loc
  );

  const notesSummary = [
    uniqueInterests.length ? `Interests: ${uniqueInterests.join(', ')}` : '',
    uniqueLocations.length ? `Location: ${uniqueLocations.join(', ')}` : '',
    'Goal: Improve orders',
  ]
    .filter(Boolean)
    .join(' | ');

  return {
    json: {
      approval_id: data.approval_id,
      message_id: data.message_id,
      status: String(data.approval_status || '').toLowerCase(),
      objective: data.objective || 'repeat_inquiry',
      previous_content: cleanMessage,
      lead: {
        id: data.lead_id,
        name: (data.lead_name || '').trim(),
        restaurant_name: (data.restaurant_name || '').trim(),
        phone: cleanPhone,
        email: (data.lead_email || '').trim(),
        source: (data.lead_source || 'instagram ads').trim(),
        notes: notesSummary || rawNotes.trim(),
        interests: uniqueInterests,
        location: uniqueLocations.join(', ') || 'Cairo',
      },
      reviewed_at: data.reviewed_at,
    },
  };
});

