const llmItems = $input.all();
const sourceItems = $('Code in JavaScript').all();

function pickNonEmpty(...vals) {
  for (const v of vals) {
    if (v !== undefined && v !== null && String(v).trim() !== '') {
      return String(v).trim();
    }
  }
  return '';
}

return llmItems.map((item, idx) => {
  const src = sourceItems[idx]?.json || {};
  const srcLead = src.lead || {};
  const out = item.json || {};
  const parsed = typeof out.output === 'object' && out.output !== null ? out.output : out;

  const rawPhone = pickNonEmpty(
    parsed.lead_phone,
    src.lead_phone,
    srcLead.phone,
    src.phone_digits,
    srcLead.phone_digits
  ).replace(/\D/g, '');

  let cleanPhone = rawPhone;
  if (cleanPhone.startsWith('00')) cleanPhone = cleanPhone.slice(2);
  if (/^01[0125]\d{8}$/.test(cleanPhone)) cleanPhone = '2' + cleanPhone;
  else if (/^1[0125]\d{8}$/.test(cleanPhone)) cleanPhone = '20' + cleanPhone;

  const followupText = pickNonEmpty(
    parsed.followup_message,
    parsed.text,
    out.text,
    out.response
  );

  const leadName = pickNonEmpty(
    parsed.lead_name,
    src.lead_name,
    srcLead.name
  );

  const restaurantName = pickNonEmpty(
    parsed.restaurant_name,
    src.restaurant_name,
    srcLead.restaurant_name
  );

  return {
    json: {
      lead_name: leadName,
      lead_phone: cleanPhone,
      restaurant_name: restaurantName,
      followup_text: followupText,
      approval_id: src.approval_id ?? null,
      message_id: src.message_id ?? null,
      lead_id: src.lead_id ?? srcLead.id ?? null,
    },
  };
});

return $input.all().map((item) => {
  const j = item.json || {};

  const leadName = String(j.lead_name || 'Lead').trim();
  const restaurant = String(j.restaurant_name || '').trim();
  const phone = String(j.lead_phone || '').trim();
  const followupText = String(j.followup_text || '').trim();

  return {
    json: {
      lead_id: j.lead_id,
      lead_name: leadName,
      lead_phone: phone,
      title: restaurant ? `Follow up: ${leadName} (${restaurant})` : `Follow up: ${leadName}`,
      description: followupText,
      priority: 'Medium',
      due_at: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
      status: 'Pending',
      assigned_to: null,
      approval_id: j.approval_id || null,
      message_id: j.message_id || null,
    },
  };
});

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();
